( #{item.cntrSn}, (SELECT IFNULL(MAX(USE_SN), 0) + 1 FROM G_CNTR_USE_POINT WHERE CNTR_SN = #{item.cntrSn}), , #{item.cntrBlcePoint}, #{item.userId}, #{item.psitnLocgovCode}, #{item.cntrLocgovCode}, #{item.useSeCode}, #{item.useCn}, '0', NULL, 0, , 0,
)
